if (pm.response.code === 201) {
  const res = pm.response.json();
  pm.environment.set('ratepayer_id', res.id);
  if (res.otp && res.otp.devOtpCode) {
    pm.environment.set('ratepayer_otp_code', res.otp.devOtpCode);
  }
  pm.expect(res).to.have.property('completion');
  pm.expect(res.completion).to.have.property('completionPercentage');
  pm.expect(res.completion).to.have.property('missingSections');
}

if (pm.response.code === 201) {
  const res = pm.response.json();
  pm.environment.set('concession_client_id', res.clientId);
  pm.environment.set('concession_client_secret', res.clientSecret);
}

if (pm.response.code === 201) {
  const res = pm.response.json();
  pm.environment.set('concession_id', res.id);
  if (res.apiClient) {
    pm.environment.set('concession_client_id', res.apiClient.clientId);
    pm.environment.set('concession_client_secret', res.apiClient.clientSecret);
  }
}

